let init=t=>{document.querySelectorAll(t).forEach(t=>{if("1"!==t.dataset.initialized){t.dataset.initialized="1";let e=t.querySelector('[data-region="day-detail"]');t.querySelectorAll("[data-detail]").forEach(t=>{t.addEventListener("click",()=>{e&&(e.textContent=t.dataset.detail||"")})})}})};export{init};